"""Dataset, split and model provenance manifests (no data is moved, copied or downloaded).

    python scripts/build_manifests.py

Writes
  data/manifests/datasets.json   every dataset: role (raw / processed / annotations / benchmark), local paths, size,
                                 completeness, license, commercial use, source, how it is split, what used it
  data/manifests/models.json     every pretrained and trained model: license, commercial use, training data
  data/splits/egoblind_{train,val,test}.jsonl   one line per source video: split rule, download / cache / scenario status,
                                 question and weak-event counts (split by video, never by frame)
  data/splits/campusbench_v2_{train,val,test}.jsonl   one line per scenario: kind, seed, OOD flag
  models/<dir>/PROVENANCE.json   for each trained model directory: training domains and the resulting usage restriction

The roadmap's raw / processed / annotations / benchmarks / splits / manifests layout is expressed through the `role` field
and these manifests instead of by moving folders, because running jobs and every script read the current paths.
"""
import json, os, subprocess, sys, time
from pathlib import Path
