MAN, SPL = ROOT / "data" / "manifests", ROOT / "data" / "splits"
MAN.mkdir(parents=True, exist_ok=True); SPL.mkdir(parents=True, exist_ok=True)


def du_gb(p: Path) -> float:
    if not p.exists():
        return 0.0
    out = subprocess.run(["du", "-sk", str(p)], capture_output=True, text=True).stdout.split()
    return round(int(out[0]) / 1e6, 3) if out else 0.0


def count(p: Path, pattern: str) -> int:
    return sum(1 for _ in p.glob(pattern)) if p.exists() else 0


