NONCOMMERCIAL = ("egoblind", "guidedog", "blv", "dada", "jrdb", "ego4d", "aria", "walkvlm")
for sub in sorted(ROOT.glob("models/*/scheduler_report.json")) + sorted(ROOT.glob("models/scheduler_report.json")):
    rep = json.loads(sub.read_text())
    dom = rep.get("train_domains", "campus")
    nc = any(k in dom for k in NONCOMMERCIAL)
    ver = rep.get("campus_version") or ({66: "v1", 84: "v2"}.get(rep.get("n_train")) if "campus" in dom else None)
    if "campus" in dom and ver is None and "egoblind" in dom:
        ver = "v1"
    d = sub.parent if sub.parent.name != "models" else ROOT / "models" / "scheduler"
    entry = {"name": str(d.relative_to(ROOT)), "kind": f"learned scheduler ({rep.get('arch', 'gru')}, {rep.get('n_params', '?')} params)",
             "license": "derived from CC BY-NC 4.0 data (EgoBlind): research only" if nc else "trained on CampusBench (generated by this repository)",
             "commercial_use_permitted": "no" if nc else "yes", "trained_on": dom + (f" (CampusBench {ver})" if ver and "campus" in dom else ""),
             "selected_on": rep.get("select_domains") or rep.get("val_domains", "campus"),
             "n_train": rep.get("n_train")}
    models.append(entry)
    if d.exists():
        (d / "PROVENANCE.json").write_text(json.dumps({**entry, "generated": time.strftime("%Y-%m-%d"),
                                                       "note": "a model trained on non-commercial data stays non-commercial"}, indent=1) + "\n")

stamp = {"generated": time.strftime("%Y-%m-%d %H:%M"), "git_commit": subprocess.run(["git", "rev-parse", "--short", "HEAD"], cwd=ROOT, capture_output=True, text=True).stdout.strip()}
(MAN / "datasets.json").write_text(json.dumps({**stamp, "datasets": datasets}, indent=1) + "\n")
(MAN / "models.json").write_text(json.dumps({**stamp, "models": models}, indent=1) + "\n")

# ---- split manifests ---------------------------------------------------------------------------------------------
os.environ.pop("SEEFORME_EGOBLIND_CACHE", None)
import egoblind_common as ec
src = ec.source_recordings()
for split in ("train", "finetune", "select", "holdout", "test"):
    qs = ec.load_egoblind_questions(split)
    with open(SPL / f"egoblind_{split}.jsonl", "w") as f:
        for vid in sorted(qs):
            sc_path = ec.SCENARIOS / split / f"{vid}.json"
            n_ev = n_q = 0
            if sc_path.exists():
                sc = json.loads(sc_path.read_text())
                n_ev = sum(1 for e in sc.get("events", []) if e.get("should_speak")); n_q = sum(1 for e in sc.get("events", []) if not e.get("should_speak"))
            f.write(json.dumps({"source": "EgoBlind", "video_id": vid, "split": split, "source_recording": src.get(vid, f"clip-{vid}"),
                                "split_rule": "official test" if split == "test" else "official train, grouped by source recording (egoblind_common.train_pool_assignment)",
                                "n_questions": len(qs[vid]), "n_should_speak": n_ev, "n_quiet_windows": n_q,
                                "downloaded": ec.video_path(vid) is not None, "cache_coco": (ec.CACHE / f"{vid}.npz").exists(),
                                "cache_open_vocab": (ROOT / "data/egoblind/cache_ow" / f"{vid}.npz").exists(), "scenario": sc_path.exists(),
                                "license": "CC BY-NC 4.0"}) + "\n")
for split in ("train", "val", "test"):
    with open(SPL / f"campusbench_v2_{split}.jsonl", "w") as f:
        for p in sorted((D / "campus_v2" / split).glob("*.json")):
            sc = json.loads(p.read_text())
            f.write(json.dumps({"source": "CampusBench v2", "scenario": sc["name"], "kind": sc["kind"], "seed": sc["seed"], "split": split,
                                "ood": sc["kind"] == "ood_aftermath", "license": "generated by this repository"}) + "\n")
counts = {p.name: sum(1 for _ in open(p)) for p in sorted(SPL.glob("*.jsonl"))}
print(json.dumps({"datasets": len(datasets), "models": len(models), "split_manifests": counts}, indent=1))
